import React, { useState, useRef } from 'react';
import { ImportService, ImportProgress } from '../services/importService';

interface StoryImporterProps {
  onImportComplete?: () => void;
}

const StoryImporter: React.FC<StoryImporterProps> = ({ onImportComplete }) => {
  const [isImporting, setIsImporting] = useState(false);
  const [progress, setProgress] = useState<ImportProgress | null>(null);
  const [dragActive, setDragActive] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = async (file: File) => {
    if (!file.name.endsWith('.json')) {
      alert('Please select a JSON file exported from Django admin.');
      return;
    }

    try {
      const text = await file.text();
      const data = JSON.parse(text);

      // Validate the data
      if (!ImportService.validateExportData(data)) {
        alert('Invalid export data. Please ensure this is a valid Django export file.');
        return;
      }

      setIsImporting(true);
      setProgress({
        currentStep: 'Preparing import...',
        progress: 0,
        total: 0,
        completed: 0,
        errors: []
      });

      // Create import service with progress callback
      const importService = new ImportService((progressUpdate) => {
        setProgress(progressUpdate);
      });

      // Start import
      await importService.importDjangoData(data);

      // Import completed
      setIsImporting(false);
      setProgress(null);

      if (onImportComplete) {
        onImportComplete();
      }

      alert('Import completed successfully!');

    } catch (error: any) {
      setIsImporting(false);
      alert(`Import failed: ${error.message}`);
    }
  };

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFileSelect(e.dataTransfer.files[0]);
    }
  };

  const handleFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      handleFileSelect(e.target.files[0]);
    }
  };

  const openFileDialog = () => {
    fileInputRef.current?.click();
  };

  return (
    <div className="container mt-4">
      <div className="row justify-content-center">
        <div className="col-md-8 p-0">
          <div className="card">
            {/* <div className="card-header">
              <h6 className="mb-0">
                <i className="fas fa-upload me-2"></i>
                Import Story
              </h6>
            </div> */}
            <div className="card-body">
              {!isImporting ? (
                <div>
                  <div className="mb-4">
                    <h5>Required Story Upload Structure:</h5>
                    <div className="bg-light p-3 rounded border" style={{ fontFamily: 'monospace', fontSize: '0.9rem' }}>
                      <div className="mb-2">
                        <strong className="text-primary">📄 JSON File</strong>
                      </div>
                      <div className="ms-3 mb-2">
                        <span className="text-success">├─</span> <strong>export_info</strong> <span className="badge bg-danger ms-1">Required</span>
                      </div>
                      <div className="ms-3 mb-2">
                        <span className="text-success">└─</span> <strong>comics</strong> <span className="text-muted">[array]</span> <span className="badge bg-danger ms-1">Required</span>
                        <div className="ms-4 mb-2">
                          <span className="text-primary">└─</span> <strong>Comic</strong>
                          <div className="ms-4 text-muted">
                            ├─ <strong className="text-dark">title</strong> <span className="badge bg-danger ms-1">Required</span><br/>
                            ├─ <strong className="text-dark">description</strong> <span className="badge bg-danger ms-1">Required</span><br/>
                            ├─ <strong className="text-dark">seasons</strong> <span className="text-muted">[array]</span> <span className="badge bg-danger ms-1">Required</span>
                            <div className="ms-4 mb-1">
                              <span className="text-info">└─</span> <strong>Season</strong>
                              <div className="ms-4 text-muted">
                                ├─ <strong className="text-dark">title</strong> <span className="badge bg-danger ms-1">Required</span><br/>
                                ├─ <strong className="text-dark">season_number</strong> <span className="badge bg-danger ms-1">Required</span><br/>
                                └─ <strong className="text-dark">episodes</strong> <span className="text-muted">[array]</span> <span className="badge bg-danger ms-1">Required</span>
                                <div className="ms-4 mb-1">
                                  <span className="text-warning">└─</span> <strong>Episode</strong>
                                  <div className="ms-4 text-muted">
                                    ├─ <strong className="text-dark">title</strong> <span className="badge bg-danger ms-1">Required</span><br/>
                                    └─ <strong className="text-dark">dialogues</strong> <span className="text-muted">[array]</span> <span className="badge bg-danger ms-1">Required</span>
                                    <div className="ms-4">
                                      <span className="text-danger">└─</span> <strong>Dialogue</strong>
                                      <div className="ms-4 text-muted">
                                        ├─ <strong className="text-dark">text</strong> <span className="badge bg-danger ms-1">Required</span><br/>
                                        └─ <strong className="text-dark">order</strong> <span className="badge bg-danger ms-1">Required</span>
                                      </div>
                                    </div>
                                  </div>
                                </div>
                              </div>
                            </div>
                            └─ <strong className="text-dark">characters</strong> <span className="text-muted">[array, optional]</span>
                            <div className="ms-4">
                              <span className="text-secondary">└─</span> <strong>Character</strong>
                              <div className="ms-4 text-muted">
                                └─ <strong className="text-dark">name</strong> <span className="badge bg-danger ms-1">Required</span>
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>
                    </div>
                    <small className="text-muted mt-2 d-block">
                      <i className="fas fa-info-circle me-1"></i>
                      All other fields are optional. Export from Django admin using "Export selected comics to JSON" action.
                    </small>
                  </div>

                  <div
                    className={`border-2 border-dashed rounded p-5 text-center ${
                      dragActive ? 'border-primary bg-light' : 'border-secondary'
                    }`}
                    onDragEnter={handleDrag}
                    onDragLeave={handleDrag}
                    onDragOver={handleDrag}
                    onDrop={handleDrop}
                  >
                    <i className="fas fa-cloud-upload-alt fa-3x text-muted mb-3"></i>
                    <h5>Drop your Django export file here</h5>
                    <p className="text-muted">or</p>
                    <button
                      className="btn btn-primary"
                      onClick={openFileDialog}
                    >
                      <i className="fas fa-folder-open me-2"></i>
                      Choose File
                    </button>
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept=".json"
                      onChange={handleFileInputChange}
                      style={{ display: 'none' }}
                    />
                  </div>

                  <div className="mt-3">
                    <small className="text-muted">
                      <i className="fas fa-info-circle me-1"></i>
                      The import will create stories, seasons, episodes, and dialogues with all camera controls.
                    </small>
                  </div>
                </div>
              ) : (
                <div>
                  <div className="mb-3">
                    <h5>Importing Stories...</h5>
                    <div className="progress">
                      <div
                        className="progress-bar progress-bar-striped progress-bar-animated"
                        style={{ width: `${progress?.progress || 0}%` }}
                      >
                        {Math.round(progress?.progress || 0)}%
                      </div>
                    </div>
                  </div>

                  <div className="mb-3">
                    <strong>Current Step:</strong> {progress?.currentStep}
                  </div>

                  <div className="mb-3">
                    <strong>Progress:</strong> {progress?.completed} / {progress?.total} items
                  </div>

                  {progress?.errors && progress.errors.length > 0 && (
                    <div className="alert alert-warning">
                      <h6>Errors:</h6>
                      <ul className="mb-0">
                        {progress.errors.map((error, index) => (
                          <li key={index}>{error}</li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StoryImporter;
